mapper.update:
update member_contract_wallet wallet
set wallet.usdt_buy_principal_amount=wallet.usdt_buy_principal_amount - #{principalAmount},
    wallet.usdt_frozen_buy_position=wallet.usdt_frozen_buy_position - #{frozenPosition},
    wallet.usdt_buy_position=wallet.usdt_buy_position - #{position}
where wallet.id = #{walletId} and wallet.usdt_buy_principal_amount>=#{principalAmount}

update member_contract_wallet wallet
set wallet.usdt_sell_principal_amount=wallet.usdt_sell_principal_amount - #{principalAmount},
    wallet.usdt_frozen_sell_position=wallet.usdt_frozen_sell_position - #{frozenPosition},
    wallet.usdt_sell_position=wallet.usdt_sell_position - #{position}
where wallet.id = #{walletId} and wallet.usdt_sell_principal_amount>=#{principalAmount}
